	const EGO = {"mode": "ego", "generated": "2026-09-12", "focus": "1007", "libraryID": 1, "groups": [{"name": "05 Operation and Paraphrase Typologies", "color": "#b45309"}, {"name": "10 Reuse Transformations in Historical Texts", "color": "#c2410c"}, {"name": "20 Tagging and Insertion", "color": "#2563a8"}, {"name": "30 Choosing and Scoring the Inventory", "color": "#0d9488"}, {"name": "40 Span-Level and Instruction-Driven Editing", "color": "#7c3aed"}, {"name": "50 Edits as a Decoding Policy", "color": "#be185d"}, {"name": "60 Aligning the Two Passages", "color": "#4d7c0f"}, {"name": "70 Supervision by Construction", "color": "#a16207"}, {"name": "80 Latin Token-Level Annotation", "color": "#6b7280"}], "statuses": ["adopted", "tested", "open", "background"], "nodes": [{"id": "1007", "key": "RXEM7SUK", "libraryID": 1, "title": "GECToR – Grammatical Error Correction: Tag, Not Rewrite", "authors": ["Omelianchuk, Kostiantyn", "Atrasevych, Vitaliy", "Chernodub, Artem", "Skurzhanskyi, Oleksandr"], "first_author": "Omelianchuk", "year": 2020, "venue": "Proceedings of the Fifteenth Workshop on Innovative Use of NLP for Building Educational Applications", "doi": "10.18653/v1/2020.bea-1.16", "url": "", "abstract": "In this paper, we present a simple and efficient GEC sequence tagger using a Transformer encoder.Our system is pre-trained on synthetic data and then fine-tuned in two stages: first on errorful corpora, and second on a combination of errorful and error-free parallel corpora.We design custom token-level transformations to map input tokens to target corrections.Our best single-model/ensemble GEC tagger achieves an F 0.5 of 65.3/66.5 on CoNLL-2014 (test) and F 0.5 of 72.4/73.6 on BEA-2019 (test).Its inference speed is up to 10 times as fast as a Transformer-based seq2seq GEC system.The code and t", "notes": [], "group": "20 Tagging and Insertion", "status": "adopted", "editable": true, "resolved": true, "citations": {"openalex": 19, "semanticscholar": 404}, "refs_found": {"openalex": 23, "semanticscholar": 28}}, {"id": "1009", "key": "BNJJR5AR", "libraryID": 1, "title": "Encode, Tag, Realize: High-Precision Text Editing", "authors": ["Malmi, Eric", "Krause, Sebastian", "Rothe, Sascha", "Mirylenka, Daniil", "Severyn, Aliaksei"], "first_author": "Malmi", "year": 2019, "venue": "Proceedings of the 2019 Conference on Empirical Methods in Natural Language Processing and the 9th International Joint Conference on Natural Language Processing (EMNLP-IJCNLP)", "doi": "10.18653/v1/D19-1510", "url": "", "abstract": "Eric Malmi, Sebastian Krause, Sascha Rothe, Daniil Mirylenka, Aliaksei Severyn. Proceedings of the 2019 Conference on Empirical Methods in Natural Language Processing and the 9th International Joint Conference on Natural Language Processing (EMNLP-IJCNLP). 2019.", "notes": [], "group": "20 Tagging and Insertion", "status": "adopted", "editable": true, "resolved": true, "citations": {"openalex": 155, "semanticscholar": 194}, "refs_found": {"openalex": 49, "semanticscholar": 51}}, {"id": "1010", "key": "YWHKZJ2Y", "libraryID": 1, "title": "Parallel Iterative Edit Models for Local Sequence Transduction", "authors": ["Awasthi, Abhijeet", "Sarawagi, Sunita", "Goyal, Rasna", "Ghosh, Sabyasachi", "Piratla, Vihari"], "first_author": "Awasthi", "year": 2019, "venue": "Proceedings of the 2019 Conference on Empirical Methods in Natural Language Processing and the 9th International Joint Conference on Natural Language Processing (EMNLP-IJCNLP)", "doi": "10.18653/v1/D19-1435", "url": "", "abstract": "Abhijeet Awasthi, Sunita Sarawagi, Rasna Goyal, Sabyasachi Ghosh, Vihari Piratla. Proceedings of the 2019 Conference on Empirical Methods in Natural Language Processing and the 9th International Joint Conference on Natural Language Processing (EMNLP-IJCNLP). 2019.", "notes": [], "group": "20 Tagging and Insertion", "status": "adopted", "editable": true, "resolved": true, "citations": {"openalex": 146, "semanticscholar": 164}, "refs_found": {"openalex": 48, "semanticscholar": 42}}, {"id": "1013", "key": "SF8B7MBN", "libraryID": 1, "title": "An Extended Sequence Tagging Vocabulary for Grammatical Error Correction", "authors": ["Mesham, Stuart", "Bryant, Christopher", "Rei, Marek", "Yuan, Zheng"], "first_author": "Mesham", "year": 2023, "venue": "Findings of the Association for Computational Linguistics: EACL 2023", "doi": "10.18653/v1/2023.findings-eacl.119", "url": "", "abstract": "We extend a current sequence-tagging approach to Grammatical Error Correction (GEC) by introducing specialised tags for spelling correction and morphological inflection using the SymSpell and LemmInflect algorithms.Our approach improves generalisation: the proposed new tagset allows a smaller number of tags to correct a larger range of errors.Our results show a performance improvement both overall and in the targeted error categories.We further show that ensembles trained with our new tagset outperform those trained with the baseline tagset on the public BEA benchmark.", "notes": [], "group": "30 Choosing and Scoring the Inventory", "status": "adopted", "editable": true, "resolved": true, "citations": {"openalex": 9, "semanticscholar": 13}, "refs_found": {"openalex": 32, "semanticscholar": 34}}, {"id": "1014", "key": "DHN2U43X", "libraryID": 1, "title": "Pillars of Grammatical Error Correction: Comprehensive Inspection of Contemporary Approaches in the Era of Large Language Models", "authors": ["Omelianchuk, Kostiantyn", "Liubonko, Andrii", "Skurzhanskyi, Oleksandr", "Chernodub, Artem", "Korniienko, Oleksandr", "Samokhin, Igor"], "first_author": "Omelianchuk", "year": 2024, "venue": "Proceedings of the 19th Workshop on Innovative Use of NLP for Building Educational Applications (BEA 2024)", "doi": "10.48550/arxiv.2404.14914", "url": "", "abstract": "In this paper, we carry out experimental research on Grammatical Error Correction, delving into the nuances of single-model systems, comparing the efficiency of ensembling and ranking methods, and exploring the application of large language models to GEC as single-model systems, as parts of ensembles, and as ranking methods. We set new state-of-the-art performance with F_0.5 scores of 72.8 on CoNLL-2014-test and 81.4 on BEA-test, respectively. To support further advancements in GEC and ensure the reproducibility of our research, we make our code, trained models, and systems' outputs publicly a", "notes": [], "group": "30 Choosing and Scoring the Inventory", "status": "adopted", "editable": true, "resolved": true, "citations": {"openalex": 2, "semanticscholar": 14}, "refs_found": {"openalex": 0, "semanticscholar": 32}}, {"id": "1015", "key": "AK74G8DP", "libraryID": 1, "title": "Automatic Annotation and Evaluation of Error Types for Grammatical Error Correction", "authors": ["Bryant, Christopher", "Felice, Mariano", "Briscoe, Ted"], "first_author": "Bryant", "year": 2017, "venue": "Proceedings of the 55th Annual Meeting of the Association for Computational Linguistics (Volume 1: Long Papers)", "doi": "10.18653/v1/P17-1074", "url": "", "abstract": "Until now, error type performance for Grammatical Error Correction (GEC) systems could only be measured in terms of recall because system output is not annotated.To overcome this problem, we introduce ERRANT, a grammatical ERRor ANnotation Toolkit designed to automatically extract edits from parallel original and corrected sentences and classify them according to a new, dataset-agnostic, rulebased framework.This not only facilitates error type evaluation at different levels of granularity, but can also be used to reduce annotator workload and standardise existing GEC datasets.Human experts rat", "notes": [], "group": "30 Choosing and Scoring the Inventory", "status": "adopted", "editable": true, "resolved": true, "citations": {"openalex": 292, "semanticscholar": 381}, "refs_found": {"openalex": 20, "semanticscholar": 23}}, {"id": "1018", "key": "4VFDWYG5", "libraryID": 1, "title": "Reducing Sequence Length by Predicting Edit Spans with Large Language Models", "authors": ["Kaneko, Masahiro", "Okazaki, Naoaki"], "first_author": "Kaneko", "year": 2023, "venue": "Proceedings of the 2023 Conference on Empirical Methods in Natural Language Processing", "doi": "10.18653/v1/2023.emnlp-main.619", "url": "", "abstract": "Large Language Models (LLMs) have demonstrated remarkable performance in various tasks and gained significant attention.LLMs are also used for local sequence transduction tasks, including grammatical error correction (GEC) and formality style transfer, where most tokens in a source text are kept unchanged.However, the models that generate all target tokens in such tasks have a tendency to simply copy the input text as is, without making needed changes, because the difference between input and output texts is minimal in the training data.This is also inefficient because the computational cost g", "notes": [], "group": "40 Span-Level and Instruction-Driven Editing", "status": "open", "editable": true, "resolved": true, "citations": {"openalex": 4, "semanticscholar": 6}, "refs_found": {"openalex": 79, "semanticscholar": 85}}, {"id": "1022", "key": "TGMXBJA4", "libraryID": 1, "title": "DiffusER: Diffusion via Edit-based Reconstruction", "authors": ["Reid, Machel", "Hellendoorn, Vincent Josua", "Neubig, Graham"], "first_author": "Reid", "year": 2023, "venue": "The Eleventh International Conference on Learning Representations (ICLR 2023)", "doi": "10.48550/arXiv.2210.16886", "url": "", "abstract": "In text generation, models that generate text from scratch one token at a time are currently the dominant paradigm. Despite being performant, these models lack the ability to revise existing text, which limits their usability in many practical scenarios. We look to address this, with DiffusER (Diffusion via Edit-based Reconstruction), a new edit-based generative model for text based on denoising diffusion models -- a class of models that use a Markov chain of denoising steps to incrementally generate data. DiffusER is not only a strong generative model in general, rivalling autoregressive mode", "notes": [], "group": "50 Edits as a Decoding Policy", "status": "adopted", "editable": true, "resolved": true, "citations": {"openalex": 8, "semanticscholar": 60}, "refs_found": {"openalex": 0, "semanticscholar": 34}}], "edges": [{"source": "1015", "target": "1007", "via": ["openalex", "semanticscholar"]}, {"source": "1009", "target": "1007", "via": ["openalex", "semanticscholar"]}, {"source": "1007", "target": "1018", "via": ["semanticscholar"]}, {"source": "1007", "target": "1014", "via": ["semanticscholar"]}, {"source": "1007", "target": "1013", "via": ["semanticscholar"]}, {"source": "1007", "target": "1022", "via": ["semanticscholar"]}, {"source": "1010", "target": "1007", "via": ["openalex", "semanticscholar"]}], "resolved": true, "refs_total": 23, "citations_total": 404, "cacheSize": 49};
